import {defineComponent,h,ref,watch} from 'vue';
import {YkButton} from '../components/button/index.js';
import {YkAIKnowledgePanel} from '../blocks/ai-knowledge-panel/index.js';
import {YkAIChatDemo,demoModels} from './ai-demo.js';
import { YkCalendar } from '../components/calendar/index.js';
import { YkDatePicker } from '../components/date-picker/index.js';
import { YkFileUpload } from '../components/file-upload/index.js';
import { YkTree } from '../components/tree/index.js';
import { YkCarousel } from '../components/carousel/index.js';
import { YkToast } from '../components/toast/index.js';
import { YkCommand } from '../components/command/index.js';
import { YkSidebar } from '../components/sidebar/index.js';
import { YkChart } from '../components/chart/index.js';
import { YkTagsInput } from '../components/tags-input/index.js';
import { YkAIStreamingText } from '../ai/ai-streaming-text/index.js';
import { YkAIMessage } from '../ai/ai-message/index.js';
import { YkAIConversation } from '../ai/ai-conversation/index.js';
import { YkAIModelSelect } from '../ai/ai-model-select/index.js';
import { YkAIAttachments } from '../ai/ai-attachments/index.js';
import { YkAIPromptInput } from '../ai/ai-prompt-input/index.js';
import { YkAIToolCall } from '../ai/ai-tool-call/index.js';
import { YkAISources } from '../ai/ai-sources/index.js';
import { YkAIActivity } from '../ai/ai-activity/index.js';
import { YkAISuggestions } from '../ai/ai-suggestions/index.js';
import { YkAIArtifact } from '../ai/ai-artifact/index.js';
import { YkAIUsage } from '../ai/ai-usage/index.js';
export const v05AssetIds=["calendar", "date-picker", "file-upload", "tree", "carousel", "toast", "command", "sidebar", "chart", "tags-input", "ai-streaming-text", "ai-message", "ai-conversation", "ai-model-select", "ai-attachments", "ai-prompt-input", "ai-tool-call", "ai-sources", "ai-activity", "ai-suggestions", "ai-artifact", "ai-usage", "ai-knowledge-panel", "ai-assistant-dock", "ai-chat-page", "ai-workspace"];
export const YkV05Asset=defineComponent({name:'YkV05Asset',props:{asset:{type:String,required:true},settings:{type:Object,required:true}},emits:['action'],setup(p,{emit}){
 const value=ref(''),selected=ref(''),files=ref([]),tags=ref(['Vue','Design']),open=ref(false),toast=ref(true),index=ref(0),checked=ref([]),removed=ref([]),query=ref('');
 watch(()=>p.settings.dateValue,v=>value.value=v||'',{immediate:true});watch(()=>p.settings.value,v=>query.value=v||'',{immediate:true});
 watch(()=>p.asset,()=>{selected.value='';files.value=[];open.value=false;toast.value=true;index.value=0;checked.value=[];removed.value=[];});
 const action=(action,value)=>emit('action',{action,value});
 const sourceItems=s=>s.items.map(i=>({id:i.value,title:i.label,url:i.content||'',description:'公开资料入口；由应用决定是否读取。'}));
 return()=>{const s=p.settings,items=s.items||[];
 switch(p.asset){
 case 'calendar':return h(YkCalendar,{modelValue:value.value,label:s.label,disabled:s.disabled,weekStartsOn:s.weekStartsOn==='sunday'?0:1,'onUpdate:modelValue':v=>{value.value=v;action('update',v);}});
 case 'date-picker':return h(YkDatePicker,{modelValue:value.value,label:s.label,disabled:s.disabled,'onUpdate:modelValue':v=>{value.value=v;action('update',v);}});
 case 'file-upload':return h(YkFileUpload,{modelValue:files.value,label:s.label,disabled:s.disabled,maxFiles:s.maxFiles,maxSize:s.maxFileMB*1048576,accept:s.accept,'onUpdate:modelValue':v=>{files.value=v;action('files',v.map(f=>({name:f.name,size:f.size})));},onReject:v=>action('reject',v.map(i=>({name:i.file.name,reason:i.reason})))});
 case 'tree':return h(YkTree,{label:s.label,disabled:s.disabled,items:[{value:'root',label:s.label,children:items}],modelValue:selected.value,'onUpdate:modelValue':v=>{selected.value=v;action('select',v);}});
 case 'carousel':return h(YkCarousel,{label:s.label,items,loop:s.loop,modelValue:index.value,'onUpdate:modelValue':v=>{index.value=v;action('update',v);}});
 case 'toast':return h('div',{class:'yk-v05-stack'},[h(YkButton,{variant:'outline',onClick:()=>toast.value=true},()=> '显示轻提示'),h(YkToast,{open:toast.value,title:s.label,description:s.description,duration:s.toastDuration,tone:s.tone,'onUpdate:open':v=>{toast.value=v;action('open',v);}})]);
 case 'command':return h('div',{},[h(YkButton,{variant:'outline',onClick:()=>open.value=true},()=>s.label),h(YkCommand,{open:open.value,label:s.label,items,'onUpdate:open':v=>open.value=v,onSelect:item=>action('select',item.value)})]);
 case 'sidebar':return h(YkSidebar,{brand:s.label,items,collapsed:s.collapsed,modelValue:selected.value||items[0]?.value,'onUpdate:modelValue':v=>{selected.value=v;action('navigate',v);},'onUpdate:collapsed':v=>action('collapsed',v)});
 case 'chart':return h(YkChart,{label:s.label,data:items.map(i=>({label:i.label,value:Number(i.content)})),kind:s.chartKind,showTable:s.showTable});
 case 'tags-input':return h(YkTagsInput,{label:s.label,placeholder:s.placeholder,disabled:s.disabled,max:s.maxTags,modelValue:tags.value,'onUpdate:modelValue':v=>{tags.value=v;action('update',v);}});
 case 'ai-streaming-text':return h(YkAIStreamingText,{content:s.contentText,streaming:s.aiStatus==='streaming',cursor:s.showCursor});
 case 'ai-message':return h(YkAIMessage,{role:s.messageRole,content:s.contentText,status:s.aiStatus,appearance:s.messageAppearance,showAvatar:s.showAvatar,showActions:s.showActions,onCopy:v=>action('copy',v),onFeedback:v=>action('feedback',v),onRetry:()=>action('retry')});
 case 'ai-conversation':return h(YkAIConversation,{messages:items.map((i,n)=>({id:i.value,name:i.label,role:n%2?'assistant':'user',content:i.content||i.label,status:n===items.length-1?s.aiStatus:'success'})),height:s.chatHeight,streaming:s.aiStatus==='streaming',appearance:s.messageAppearance,showAvatar:s.showAvatar,onFeedback:v=>action('feedback',v),onRetry:id=>action('retry',id)});
 case 'ai-model-select':return h(YkAIModelSelect,{options:items,modelValue:selected.value||items[0]?.value,disabled:s.disabled,label:s.label,'onUpdate:modelValue':v=>{selected.value=v;action('model',v);}});
 case 'ai-attachments':return h(YkAIAttachments,{items:items.filter(i=>!removed.value.includes(i.value)).map(i=>({id:i.value,name:i.label,size:2048})),removable:s.removable,disabled:s.disabled,onRemove:id=>{removed.value.push(id);action('remove',id);}});
 case 'ai-prompt-input':return h(YkAIPromptInput,{modelValue:query.value,model:selected.value||demoModels[0].value,models:demoModels,placeholder:s.placeholder,label:s.label,busy:s.loading,disabled:s.disabled,rows:s.rows,sendKey:s.sendKey,attachments:s.attachmentEnabled,'onUpdate:modelValue':v=>query.value=v,'onUpdate:model':v=>selected.value=v,onSubmit:v=>action('submit',{text:v.text,model:v.model,fileCount:v.files.length}),onStop:()=>action('stop'),onReject:v=>action('reject',v.map(x=>x.reason))});
 case 'ai-tool-call':return h(YkAIToolCall,{name:s.label,status:s.toolStatus,input:s.toolInput,output:s.toolOutput,defaultOpen:s.expanded,onApprove:()=>action('approve'),onReject:()=>action('reject')});
 case 'ai-sources':return h(YkAISources,{items:sourceItems(s),label:s.label,defaultOpen:s.expanded});
 case 'ai-activity':return h(YkAIActivity,{label:s.label,items:items.map(i=>({id:i.value,label:i.label,status:['pending','running','success','error'].includes(i.content)?i.content:'pending'}))});
 case 'ai-suggestions':return h(YkAISuggestions,{items,layout:s.suggestionLayout,disabled:s.disabled,onSelect:item=>action('select',item)});
 case 'ai-artifact':return h(YkAIArtifact,{title:s.label,content:s.contentText,summary:s.description,language:s.codeLanguage,downloadable:s.downloadable,onCopy:v=>action('copy',v),onDownload:()=>action('download')});
 case 'ai-usage':return h(YkAIUsage,{used:s.contextUsed,limit:s.contextLimit,label:s.label});
 case 'ai-knowledge-panel':return h(YkAIKnowledgePanel,{title:s.label,items:sourceItems(s),selected:checked.value,'onUpdate:selected':v=>{checked.value=v;action('context-selection',v);}});
 case 'ai-assistant-dock':return h(YkAIChatDemo,{settings:s,variant:'dock',onAction:e=>emit('action',e)});
 case 'ai-chat-page':case 'ai-workspace':return h(YkAIChatDemo,{settings:s,variant:p.asset==='ai-workspace'?'workspace':'chat',onAction:e=>emit('action',e)});
 default:throw new Error('Missing v0.5 renderer: '+p.asset);
 }
 };
}});
